//! Independent LLVM corpus check of gfx1030 instruction identification (#209).
//!
//! `llvm/corpus.tsv` is generated by `llvm/corpus.py` from LLVM 23.1.6 alone:
//! llvm-mc assembles the original instructions in `llvm/corpus.s`, and
//! llvm-objdump decodes byte probes built from each metadata form's
//! identifying bits (one with every other bit zero, two with seeded random
//! operand bits). The expected name, consumed length and extension of every
//! row are LLVM's. This test compares `identify` with them and pins what it
//! measures: per-source class counts, the exact rows where the two disagree
//! for assembled and zero-operand inputs, and a digest of the random-probe
//! classification.
//!
//! Identification is not execution support: a row counted as identified only
//! means both agree on which instruction the bytes are and how long it is.

use std::collections::BTreeMap;

use xenora_isa::meta::{FORMS, Identified, IdentifyError, VectorControl, identify};

const CORPUS: &str = include_str!("llvm/corpus.tsv");

/// Row classes, in report order.
const CLASSES: [&str; 9] = [
    "identified",    // both decode: same name, length and extension
    "mismatch",      // both decode, but name, length or extension differ
    "oracle_only",   // LLVM decodes, identify returns an error
    "metadata_only", // identify decodes, LLVM cannot
    "both_reject",   // neither decodes
    "oracle_crash",  // llvm-objdump crashed; no oracle answer
    "truncated",     // a proper prefix: identify asks for more bytes
    "truncation_other",
    "operand_flagged", // same instruction and length; LLVM flags an operand as invalid
];
const SOURCES: [&str; 5] = [
    "asm",
    "probe-zero",
    "probe-ext",
    "probe-random",
    "truncation",
];

fn base_name(mnemonic: &str) -> String {
    let upper = mnemonic.to_ascii_uppercase();
    ["_E32", "_E64", "_SDWA", "_DPP"]
        .into_iter()
        .find_map(|suffix| upper.strip_suffix(suffix))
        .unwrap_or(&upper)
        .to_owned()
}

fn extension(found: &Identified) -> String {
    let nsa = format!("nsa{}", found.trailer.nsa_dwords);
    let mut parts = Vec::new();
    if found.trailer.literal {
        parts.push("literal");
    }
    match found.trailer.vector_control {
        Some(VectorControl::Sdwa) => parts.push("sdwa"),
        Some(VectorControl::Dpp8 {
            fetch_inactive: false,
        }) => parts.push("dpp8"),
        Some(VectorControl::Dpp8 {
            fetch_inactive: true,
        }) => parts.push("dpp8fi"),
        Some(VectorControl::Dpp16) => parts.push("dpp16"),
        None => {}
    }
    if found.trailer.nsa_dwords != 0 {
        parts.push(&nsa);
    }
    if parts.is_empty() {
        "-".into()
    } else {
        parts.join("+")
    }
}

struct Row<'a> {
    source: usize,
    form: Option<&'static str>,
    family: &'a str,
    hex: &'a str,
    class: usize,
    detail: String,
}

fn classify(line: &str) -> Row<'_> {
    let [source, hex, mnemonic, len, ext, note] = line.split('\t').collect::<Vec<_>>()[..] else {
        panic!("bad corpus row: {line}");
    };
    let source = SOURCES
        .iter()
        .position(|s| *s == source)
        .unwrap_or_else(|| panic!("bad source: {line}"));
    let (family, text) = note.split_once(' ').unwrap();
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    let len: usize = len.parse().unwrap();
    let found = identify(&bytes);
    let answer = match &found {
        Ok(found) => format!(
            "{} ({} bytes, {})",
            found.form.name,
            found.len,
            extension(found)
        ),
        Err(error) => format!("{error:?}"),
    };
    let mut differences = Vec::new();
    // LLVM decoded the words but flagged an operand the instruction cannot
    // take. identify does not validate operands; it must still agree on the
    // instruction and its length, or reject the extension outright.
    let (flagged, mnemonic) = match mnemonic.strip_prefix("invalid-operand:") {
        Some(mnemonic) => (true, mnemonic),
        None => (false, mnemonic),
    };
    let class = match (mnemonic, &found) {
        ("truncated", Err(IdentifyError::Truncated { needed })) if *needed > bytes.len() => 6,
        ("truncated", _) => 7,
        ("crashed", _) => 5,
        ("invalid", Err(_)) => 4,
        ("invalid", Ok(_)) => 3,
        (_, Err(IdentifyError::InvalidExtension(_))) if flagged => 4,
        (_, Err(_)) => 2,
        (_, Ok(found)) => {
            if found.form.name != base_name(mnemonic) {
                differences.push("name");
            }
            if found.len != len {
                differences.push("length");
            }
            if extension(found) != ext {
                differences.push("extension");
            }
            if !differences.is_empty() {
                1
            } else if flagged {
                8
            } else {
                0
            }
        }
    };
    let kind = if differences.is_empty() {
        CLASSES[class].to_owned()
    } else {
        format!("mismatch/{}", differences.join("+"))
    };
    Row {
        source,
        form: found.ok().map(|found| found.form.name),
        family,
        hex,
        class,
        detail: format!("{kind}: {hex} | LLVM {text} ({len} bytes, {ext}) | Xenora {answer}"),
    }
}

/// FNV-1a over the sorted `class hex` lines, to pin thousands of rows compactly.
fn digest(lines: &[String]) -> u64 {
    lines
        .iter()
        .flat_map(|l| l.bytes().chain(*b"\n"))
        .fold(0xcbf2_9ce4_8422_2325, |hash, byte| {
            (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3)
        })
}

// Measured against LLVM 23.1.6 on 2026-11-24. Any change needs the affected
// rows reviewed against LLVM, not an update of these numbers alone.
// Rows: one per source, columns in CLASSES order.
const COUNTS: [[usize; 9]; 5] = [
    [317, 0, 0, 0, 0, 0, 0, 0, 0],      // asm
    [1365, 0, 0, 82, 0, 0, 0, 0, 18],   // probe-zero
    [1397, 6, 21, 0, 752, 0, 0, 0, 3],  // probe-ext
    [1236, 0, 0, 1678, 3, 2, 0, 0, 11], // probe-random
    [0, 0, 0, 0, 0, 0, 87, 0, 0],       // truncation
];
/// Every assembled, zero-operand or extension-probe row where the two disagree
/// (neither `identified` nor `both_reject`), as `class hex`, sorted by hex.
const DISAGREEMENTS: &str = include_str!("llvm/corpus_disagreements.txt");
/// Digest of the sorted `class hex` lines of the random probes.
const RANDOM_DIGEST: u64 = 0x32fb_5d7d_0826_ce14;

#[test]
fn identification_agrees_with_the_llvm_corpus() {
    let mut lines = CORPUS.lines();
    assert_eq!(
        lines.next(),
        Some("source\thex\tllvm_mnemonic\tllvm_len\tllvm_ext\tnote")
    );
    let rows: Vec<_> = lines.map(classify).collect();
    let mut counts = [[0usize; 9]; 5];
    let mut by_family = BTreeMap::<&str, [usize; 9]>::new();
    for row in &rows {
        counts[row.source][row.class] += 1;
        by_family.entry(row.family).or_default()[row.class] += 1;
    }
    println!("{:9} {}", "family", CLASSES.join(" "));
    for (family, c) in &by_family {
        print!("{family:9}");
        for (name, n) in CLASSES.iter().zip(c) {
            print!(" {n:>w$}", w = name.len());
        }
        println!();
    }
    for (source, c) in SOURCES.iter().zip(&counts) {
        println!("{source:13} {c:?}");
    }
    let mut disagreements: Vec<_> = rows
        .iter()
        .filter(|r| r.source < 3 && !matches!(r.class, 0 | 4))
        .collect();
    disagreements.sort_unstable_by_key(|r| r.hex);
    for r in &disagreements {
        println!("{}", r.detail);
    }
    let disagreements: Vec<_> = disagreements
        .iter()
        .map(|r| format!("{} {}", CLASSES[r.class], r.hex))
        .collect();
    let mut random: Vec<_> = rows
        .iter()
        .filter(|r| r.source == 3)
        .map(|r| format!("{} {}", CLASSES[r.class], r.hex))
        .collect();
    random.sort_unstable();
    let random_digest = digest(&random);
    println!("random digest {random_digest:#018x}");
    for r in rows
        .iter()
        .filter(|r| r.source == 3 && r.class == 1)
        .take(5)
    {
        println!("random example {}", r.detail);
    }

    // Distinct metadata forms: agreed by LLVM on at least one row, or only
    // ever decoded by Xenora (LLVM rejected every probe of that form).
    let mut forms = BTreeMap::<&str, (usize, usize)>::new();
    for row in &rows {
        if let Some(form) = row.form {
            let entry = forms.entry(form).or_default();
            match row.class {
                0 | 8 => entry.0 += 1,
                3 => entry.1 += 1,
                _ => {}
            }
        }
    }
    let agreed = forms.values().filter(|(a, _)| *a > 0).count();
    let never: Vec<_> = forms
        .iter()
        .filter(|(_, (a, m))| *a == 0 && *m > 0)
        .map(|(name, _)| *name)
        .collect();
    println!(
        "distinct forms seen {}: agreed {agreed}, metadata-only on every row {}",
        forms.len(),
        never.len()
    );
    println!("never decoded by LLVM: {}", never.join(" "));
    let mut all_names: Vec<_> = FORMS.iter().map(|form| form.name).collect();
    all_names.sort_unstable();
    all_names.dedup();
    let unseen: Vec<_> = all_names
        .iter()
        .filter(|name| !forms.contains_key(*name))
        .collect();
    println!(
        "metadata: {} forms, {} distinct names, {} names with no corpus row: {unseen:?}",
        FORMS.len(),
        all_names.len(),
        unseen.len()
    );
    assert_eq!(counts, COUNTS, "class counts per source changed");
    let pinned: Vec<_> = DISAGREEMENTS
        .lines()
        .filter(|line| !line.starts_with('#'))
        .collect();
    assert_eq!(disagreements, pinned, "disagreeing rows changed");
    assert_eq!(
        random_digest, RANDOM_DIGEST,
        "random-probe classification changed"
    );
}

#[test]
#[ignore = "requires LLVM with the gfx1030 AMDGPU target (set LLVM_BIN)"]
fn llvm_corpus_is_fresh() {
    let bin = std::env::var("LLVM_BIN").expect("LLVM_BIN");
    let status = std::process::Command::new("python3")
        .arg(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/llvm/corpus.py"))
        .args(["--llvm-bin", &bin, "--check"])
        .status()
        .expect("run corpus.py");
    assert!(
        status.success(),
        "corpus.tsv differs from LLVM's current output"
    );
}
